(6968974, 1049986, 54446, '<td valign="top">Pretty good.  Some blocked up shadows.  My favorite part of the scene is the prairie grass.  I might have cropped out part of the sky.  7</td>', 'Pretty good.  Some blocked up shadows.  My favorite part of the scene is the prairie grass.  I might have cropped out part of the sky.  7', '2013-02-01 11:32:16.000000', NULL, 1),
(6968977, 1051052, 54446, '<td valign="top">Very nice capture of a pensive moment of this child.  The strength of this image is the capture of the warm/natural light.  7</td>', 'Very nice capture of a pensive moment of this child.  The strength of this image is the capture of the warm/natural light.  7', '2013-02-01 11:33:37.000000', NULL, 1),
(6968978, 1051164, 30669, '<td valign="top">My guess.....Cape town? Nice shot. Like the freighter right there in the middle in distance.</td>', 'My guess.....Cape town? Nice shot. Like the freighter right there in the middle in distance.', '2013-02-01 11:33:38.000000', NULL, 1),
