(6969853, 1049807, 60047, '<td valign="top">Nice post processing, here.</td>', 'Nice post processing, here.', '2013-02-02 10:20:13.000000', NULL, 1),
(6969854, 1052009, 101256, '<td valign="top">Best concept I''ve see so far in the challenge. Love the soft focus and the effect of the white background and dress - very clever. My only complaint is that the lighting could be a little less strong on the left side of the image, but that''s personal choice and not a technical thing. Nicely done - great capture and concept.</td>', 'Best concept I''ve see so far in the challenge. Love the soft focus and the effect of the white background and dress - very clever. My only complaint is that the lighting could be a little less strong on the left side of the image, but that''s personal choice and not a technical thing. Nicely done - great capture and concept.', '2013-02-02 10:20:26.000000', NULL, 1),
(6969855, 1052204, 60047, '<td valign="top">I''m missing something with that title...</td>', 'I''m missing something with that title...', '2013-02-02 10:21:39.000000', NULL, 1),
(6969856, 1051008, 101256, '<td valign="top">I saw a picture in one of my hunting magazines that was very similar to this - only that one sucked and this one is terrific. Boy, it is getting hard to keep going on the voting - all of these images are terrific.  Makes one wonder.  Terrific. Well done.</td>', 'I saw a picture in one of my hunting magazines that was very similar to this - only that one sucked and this one is terrific. Boy, it is getting hard to keep going on the voting - all of these images are terrific.  Makes one wonder.  Terrific. Well done.', '2013-02-02 10:21:55.000000', NULL, 1),
(6969857, 1051906, 101256, '<td valign="top">Can''t say enough about this - simple, elegant, crisp sharp, etc., etc., etc. Wonderful imagery.</td>', 'Can''t say enough about this - simple, elegant, crisp sharp, etc., etc., etc. Wonderful imagery.', '2013-02-02 10:22:59.000000', NULL, 1),
