INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6972484, 1052162, 23484, '<td valign="top">Nice job on the star trails.</td>', 'Nice job on the star trails.', '2013-02-05 14:17:14.000000', NULL, 1),
