(6975280, 1049753, 96574, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by HarveyG:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by pamb:</b></div><hr/><i> Mark, one day I want to pick your brains over this magical marvelous wonderfully luminous way you treat light in your processing.</i></td></tr></table> <br/> <br/>It''s like Coca Cola or KFC. Secret! Well done mate. </i></td></tr></table> <br/> <br/>:)<br/> <br/>Hehe...nah, no secrets here. Just pm me Pam and I''ll be glad to explain what was done.</td>', 'Originally posted by HarveyG: Originally posted by pamb: Mark, one day I want to pick your brains over this magical marvelous wonderfully luminous way you treat light in your processing.  It''s like Coca Cola or KFC. Secret! Well done mate.   :) Hehe...nah, no secrets here. Just pm me Pam and I''ll be glad to explain what was done.', '2013-02-08 05:20:10.000000', NULL, 0),
(6975281, 1050820, 96574, '<td valign="top">As always, masterfully composed and top notch use of light. Congrats on the HM!</td>', 'As always, masterfully composed and top notch use of light. Congrats on the HM!', '2013-02-08 05:24:04.000000', NULL, 0),
(6975289, 1050318, 96574, '<td valign="top">This is such a wonderful shot.  His demeanor evokes an unspoken self-awareness that you translated perfectly into the shot.<br/>Congrats on the TT!</td>', 'This is such a wonderful shot.  His demeanor evokes an unspoken self-awareness that you translated perfectly into the shot.Congrats on the TT!', '2013-02-08 05:44:29.000000', NULL, 0),
(6975294, 1050704, 103142, '<td valign="top">You really should send this to National Geographic -- this is the most incredible shot. What a shot! What a story! What a piece of art!<br/> <br/>Huge, huge congrats!!</td>', 'You really should send this to National Geographic -- this is the most incredible shot. What a shot! What a story! What a piece of art! Huge, huge congrats!!', '2013-02-08 05:53:08.000000', NULL, 0),
