(6975466, 1050639, 61961, '<td valign="top">This photo makes me happy.  Great subject.</td>', 'This photo makes me happy.  Great subject.', '2013-02-08 09:49:07.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6975468, 1049965, 61961, '<td valign="top">I should have recognized your son!  I gave this a six, btw, I think the photo relies too much on the big black frame.  Interesting processing.  Your iphone and instagram, really?  How does one verify that for DPC?  Cheers,</td>', 'I should have recognized your son!  I gave this a six, btw, I think the photo relies too much on the big black frame.  Interesting processing.  Your iphone and instagram, really?  How does one verify that for DPC?  Cheers,', '2013-02-08 09:52:46.000000', NULL, 0),
(6975472, 1050091, 61961, '<td valign="top">Interesting how you can''t see what the woman is holding, but is there any doubt?</td>', 'Interesting how you can''t see what the woman is holding, but is there any doubt?', '2013-02-08 09:55:09.000000', NULL, 0),
(6975481, 1049510, 100831, '<td valign="top">Beautifully serene. This was an 8 from me.</td>', 'Beautifully serene. This was an 8 from me.', '2013-02-08 10:17:31.000000', NULL, 0),
(6975483, 1051862, 100831, '<td valign="top">Such a wondefully happy time! Great capture, Michelle!</td>', 'Such a wondefully happy time! Great capture, Michelle!', '2013-02-08 10:19:44.000000', NULL, 0),
(6975486, 1051982, 57447, '<td valign="top">Well done Bob!</td>', 'Well done Bob!', '2013-02-08 10:29:33.000000', NULL, 0),
(6975490, 1050704, 50641, '<td valign="top">clearly your biggest talent is knowing just how to pose your subjects ;-)  congrats on a fitting cap to an amazing year!</td>', 'clearly your biggest talent is knowing just how to pose your subjects ;-)  congrats on a fitting cap to an amazing year!', '2013-02-08 10:33:53.000000', NULL, 0),
(6975495, 1049718, 50695, '<td valign="top">that was a tragedy. Whoever has it now is doing nothing with it compared to you.</td>', 'that was a tragedy. Whoever has it now is doing nothing with it compared to you.', '2013-02-08 10:52:43.000000', NULL, 0),
(6975496, 1051863, 19825, '<td valign="top">I need to be a better commenter. This one connected with me and I lingered for a while. I liked it and gave it a 7. I remember thinking that it was a bold choice for the Best Of challenge because I thought many would mistake this as a simple snapshot, and that alone warranted a comment. I had trouble formulating a sentence on why I liked it, so I moved on too quickly -- back to the hundreds of Best of 2012 and December Free Study images still left to vote on. <br/> <br/>Had I not been in such a selfish hurry, this is what i might have said:<br/>I love the way this image captures the buzz of birthday activity and the mayhem of the cupcake table. I love the arms, the small girl pressed up to the table. I love the children''s faces focused on the cupcakes out of frame and the eye contact with the one adult in frame. A moment well captured.</td>', 'I need to be a better commenter. This one connected with me and I lingered for a while. I liked it and gave it a 7. I remember thinking that it was a bold choice for the Best Of challenge because I thought many would mistake this as a simple snapshot, and that alone warranted a comment. I had trouble formulating a sentence on why I liked it, so I moved on too quickly -- back to the hundreds of Best of 2012 and December Free Study images still left to vote on.  Had I not been in such a selfish hurry, this is what i might have said:I love the way this image captures the buzz of birthday activity and the mayhem of the cupcake table. I love the arms, the small girl pressed up to the table. I love the children''s faces focused on the cupcakes out of frame and the eye contact with the one adult in frame. A moment well captured.', '2013-02-08 10:53:51.000000', NULL, 0),
(6975502, 1051924, 50695, '<td valign="top">you found the perfect crop for this.</td>', 'you found the perfect crop for this.', '2013-02-08 10:59:22.000000', NULL, 0),
(6975505, 1051373, 30982, '<td valign="top">I liked this one very much, Janine!  You had a wonderful selection to choose from - and it''s always right to go with the one you like best!</td>', 'I liked this one very much, Janine!  You had a wonderful selection to choose from - and it''s always right to go with the one you like best!', '2013-02-08 11:03:33.000000', NULL, 0),
(6975510, 1051781, 30982, '<td valign="top">I like the moment just before take off - nicely timed!</td>', 'I like the moment just before take off - nicely timed!', '2013-02-08 11:06:31.000000', NULL, 0),
